using System;using UnityEngine;using UnityEngine.UI;using TMPro;using DG.Tweening;using LWS.TruckSports;
namespace LWS.TruckPoker {
[Serializable]public sealed class PokerPane {
 public RectTransform root;public PokerCardView[] own,board;public TMP_Text hint,bet,reason;public Slider amount;public Image[] choices;public GameObject actions;
}
public sealed class PokerPresentation:MonoBehaviour {
 public PokerMatch match;public PokerPane[] panes;public PokerCardView[] board,seatCards,spectatorBoard;public GameObject spectatorRoot;public TMP_Text[] names,stacks;public Transform[] chips,expressions;public Transform dealer,dealHand;public TMP_Text history;public Transform buttonMarker;public TMP_Text stackOption,blindOption,levelOption,lookOption,invertOption;Renderer[][] paints;MaterialPropertyBlock[] colors;Transform[] heads=new Transform[8];Quaternion[] headBasis=new Quaternion[8];int lastVersion=-1;readonly bool[] peeking=new bool[4];readonly int[] priorOwner={-1,-1,-1,-1};
 void Awake(){paints=new Renderer[8][];colors=new MaterialPropertyBlock[8];for(int i=0;i<8;i++){var all=match.avatars[i].GetComponentsInChildren<Renderer>(true);paints[i]=System.Array.FindAll(all,r=>r.name=="Cab");colors[i]=new MaterialPropertyBlock();if(paints[i].Length>0){heads[i]=paints[i][0].transform;headBasis[i]=heads[i].localRotation;}}}
 public void ResetTable(){for(int i=0;i<8;i++){colors[i].SetColor("_BaseColor",match.setup.players[i].color);colors[i].SetColor("_Color",match.setup.players[i].color);foreach(var r in paints[i])r.SetPropertyBlock(colors[i]);}lastVersion=-1;ClearPrivate();foreach(var card in board)card.Clear(true);foreach(var card in seatCards)card.Clear(false);for(int i=0;i<chips.Length;i++){chips[i].DOKill();chips[i].localScale=Vector3.one;}foreach(var e in expressions){e.DOKill();e.localRotation=Quaternion.identity;}if(dealer!=null){dealer.DOKill();dealer.localRotation=Quaternion.identity;}}
 public void ClearPrivate(){if(panes==null)return;for(int i=0;i<panes.Length;i++){peeking[i]=false;foreach(var card in panes[i].own)if(card!=null)card.Clear(true);}}
 public void Layout(){ClearPrivate();for(int i=0;i<panes.Length;i++){bool active=i<match.HumanViews;panes[i].root.gameObject.SetActive(active);if(!active){priorOwner[i]=-1;continue;}var r=match.seats[i].view.rect;panes[i].root.anchorMin=r.min;panes[i].root.anchorMax=r.max;panes[i].root.offsetMin=panes[i].root.offsetMax=Vector2.zero;priorOwner[i]=match.ViewOwners[i];}}
 public void PublicStateChanged(){lastVersion=-1;RefreshPublic();}
 void RefreshPublic(){if(match.Table==null)return;var table=match.Table;var publicBoard=table.PublicBoard;for(int c=0;c<board.Length;c++)if(c<publicBoard.Length)board[c].Show(publicBoard[c]);else board[c].Clear(true);for(int c=0;c<spectatorBoard.Length;c++)if(c<publicBoard.Length)spectatorBoard[c].Show(publicBoard[c]);else spectatorBoard[c].Clear(false);for(int p=0;p<panes.Length;p++)for(int c=0;c<panes[p].board.Length;c++)if(c<publicBoard.Length)panes[p].board[c].Show(publicBoard[c]);else panes[p].board[c].Clear(false);
 for(int i=0;i<8;i++){bool active=i<match.setup.count;names[i].gameObject.SetActive(active);stacks[i].gameObject.SetActive(active);chips[i].gameObject.SetActive(active);match.avatars[i].gameObject.SetActive(active);if(!active)continue;names[i].text=match.setup.players[i].name+(i==table.Actor&&!table.HandDone?" · ACTING":"");names[i].color=match.setup.players[i].color;stacks[i].text=(i==table.Button?"BUTTON · ":"")+(i==table.SmallBlindSeat?"SB · ":i==table.BigBlindSeat?"BB · ":"")+table.Stack(i)+" CHIPS\n"+(match.PublicAction[i]??"WAITING");float height=.35f+Mathf.Log10(table.Stack(i)+1)*.22f;chips[i].DOKill();chips[i].DOScaleY(height,.18f);bool show=table.PubliclyRevealed(i);int[] cards=show?table.OwnHand(i):null;for(int n=0;n<2;n++){var card=seatCards[i*2+n];if(show)card.Show(cards[n]);else card.Clear(false);card.gameObject.SetActive(table.IsInHand(i)&&!table.IsFolded(i));}}
 if(buttonMarker!=null&&table.Button>=0)buttonMarker.position=chips[table.Button].position+Vector3.up*.25f+match.avatars[table.Button].right*.9f;if(history!=null){var log=table.History;var text=new System.Text.StringBuilder("PUBLIC ACTION HISTORY\n");for(int i=Math.Max(0,log.Count-12);i<log.Count;i++)text.AppendLine(log[i]);history.text=text.ToString();}lastVersion=match.Version;}
 public void Tick(){if(spectatorRoot!=null)spectatorRoot.SetActive(match.HumanViews==0&&match.Running&&!match.Finished);if(match.Table==null){ClearPrivate();return;}if(lastVersion!=match.Version)RefreshPublic();for(int view=0;view<panes.Length;view++){var pane=panes[view];if(view>=match.HumanViews){foreach(var card in pane.own)if(card.gameObject.activeSelf||card.HasPrivateDisplayData)card.Clear(true);continue;}int owner=match.ViewOwners[view];if(priorOwner[view]!=owner){foreach(var card in pane.own)card.Clear(true);priorOwner[view]=owner;peeking[view]=false;}bool peek=match.PeekHeld(owner);if(peek&&!peeking[view]){var cards=match.Table.OwnHand(owner);for(int c=0;c<2;c++)pane.own[c].Show(cards[c]);}else if(!peek&&(peeking[view]||pane.own[0].HasPrivateDisplayData||pane.own[1].HasPrivateDisplayData))foreach(var card in pane.own)card.Clear(true);peeking[view]=peek;if(heads[owner]!=null)heads[owner].localRotation=headBasis[owner]*Quaternion.Euler(peek?12:Mathf.Clamp(match.looks[view].Pitch*.3f,-12,12),Mathf.Clamp(match.looks[view].Yaw*.35f,-35,35),0);
 bool actor=match.Live&&!match.Handoff&&!match.Table.HandDone&&match.Table.Actor==owner&&match.setup.players[owner].source!=LWS.TruckBowling.BowlingSource.AI;pane.actions.SetActive(actor);pane.hint.text=match.setup.players[owner].source==LWS.TruckBowling.BowlingSource.AI?"AI VIEW · PRIVATE CARDS HIDDEN":match.Handoff?"PASS TO "+match.setup.players[owner].name+" · FRESH ACTION":peek?"YOUR HAND · RELEASE TO HIDE":"HOLD "+match.PeekCaption(owner)+" TO PEEK";if(!actor)continue;var v=match.Table.View(owner);pane.bet.text=(match.Selected==0?"FOLD":match.Selected==1?v.Call==0?"CHECK":"CALL "+v.Call:"RAISE TO "+match.RaiseTotal)+" · "+match.Controls(owner);pane.reason.text=!string.IsNullOrEmpty(match.Notice)?match.Notice:!v.CanRaise?v.RaiseReason:"TOTAL BET · ACTION CONFIRMS";pane.amount.minValue=Math.Min(v.MinimumRaiseTo,v.MaximumRaiseTo);pane.amount.maxValue=v.MaximumRaiseTo;pane.amount.SetValueWithoutNotify(match.RaiseTotal);pane.amount.interactable=v.CanRaise&&match.MouseOwns(view);for(int i=0;i<pane.choices.Length;i++)pane.choices[i].color=i==match.Selected?SportsBroadcastCanvas.Orange:SportsBroadcastCanvas.Raised;}}
 public void React(int seat,PokerAction action){if(seat<0||seat>=expressions.Length)return;var target=expressions[seat];target.DOKill();float pitch=action==PokerAction.Fold?14:action==PokerAction.RaiseTo?-10:5;target.DOLocalRotate(new Vector3(pitch,0,0),.18f).SetLoops(2,LoopType.Yoyo);if(dealHand!=null){dealHand.DOKill();dealHand.DOLocalRotate(new Vector3(0,seat*17-60,0),.18f).SetLoops(2,LoopType.Yoyo);}}
 public void Award(){ClearPrivate();match.feedback.Play(5,0,true);foreach(var award in match.Table.Awards)foreach(int seat in award.Winners){var target=expressions[seat];target.DOKill();target.DOLocalRotate(new Vector3(-12,0,0),.22f).SetLoops(4,LoopType.Yoyo);match.Pulse(seat,.25f,.15f);}}
 static void Caption(TMP_Text label,string value){if(label==null)return;label.text=value;var button=label.GetComponentInParent<Michsky.UI.Heat.ButtonManager>(true);if(button!=null)button.buttonText=value;}
 public void Options(){Caption(stackOption,"STACK "+match.startingStack);Caption(blindOption,"BLINDS "+match.smallBlind+" / "+match.smallBlind*2);Caption(levelOption,"LEVEL EVERY "+match.levelHands+" HANDS");Caption(lookOption,"LOOK SPEED "+SportsLookOptions.Sensitivity.ToString("0.##")+"x");Caption(invertOption,"INVERT LOOK "+(SportsLookOptions.InvertY?"ON":"OFF"));}
 void OnApplicationFocus(bool focus){if(!focus){match.ClearPeekGate();ClearPrivate();}}void OnDisable(){ClearPrivate();}void OnDestroy(){if(chips!=null)foreach(var t in chips)if(t!=null)t.DOKill();if(expressions!=null)foreach(var t in expressions)if(t!=null)t.DOKill();if(dealer!=null)dealer.DOKill();if(dealHand!=null)dealHand.DOKill();}
}
}
